-- SILO-owned bucket dashboards and a compact Marketing section on Overview.
-- Global widgets contain only configuration; each report runs under the viewer's RLS.
-- Dates stay relative. Marketing ends two days ago so Search Console has finalized days.

on conflict (id) do update set company_entity_id=null,created_by=null,name=excluded.name,description=excluded.description,visibility=excluded.visibility,filter_state=excluded.filter_state,source=excluded.source;

on conflict (id) do update set company_entity_id=null,created_by=null,name=excluded.name,description=excluded.description,visibility=excluded.visibility,filter_state=excluded.filter_state,source=excluded.source;

on conflict (id) do update set company_entity_id=null,created_by=null,name=excluded.name,description=excluded.description,visibility=excluded.visibility,filter_state=excluded.filter_state,source=excluded.source;

on conflict (id) do update set company_entity_id=null,created_by=null,name=excluded.name,description=excluded.description,visibility=excluded.visibility,filter_state=excluded.filter_state,source=excluded.source;

update public.dashboards set description='Sales, stock, open purchase orders and a separate marketing attribution snapshot. Marketing sources may be absent. Maintained by SILO; save a copy to change it.' where id='5110da5b-0000-4000-a000-000000000001' and source='system';

on conflict (id) do update set dashboard_id=excluded.dashboard_id,company_entity_id=null,created_by=null,report_id=excluded.report_id,query_index=excluded.query_index,title=excluded.title,visual_type=excluded.visual_type,visual_config=excluded.visual_config,layout=excluded.layout,sort_order=excluded.sort_order;

-- Each of the 21 current SILO reports appears on its matching bucket board.
do $$ begin
 if (select count(distinct w.report_id) from public.dashboard_widgets w join public.dashboards d on d.id=w.dashboard_id where d.id in ('5110da5b-0000-4000-a000-000000000011','5110da5b-0000-4000-a000-000000000012','5110da5b-0000-4000-a000-000000000013','5110da5b-0000-4000-a000-000000000014')) <> 21 then
   raise exception 'SILO bucket dashboards must cover all 21 current system reports';
 end if;
end $$;
